//! aKta: every summary is generated by the company's internal llama.cpp server
//! (OpenAI-compatible `llama-server`). No other LLM provider is used.

use std::time::Duration;

use log::{info, warn};
use reqwest::{redirect::Policy, Client};
use sqlx::SqlitePool;

use crate::database::repositories::setting::SettingsRepository;
use crate::summary::CustomOpenAIConfig;

pub const PROVIDER: &str = "custom-openai";
pub const DEFAULT_BASE_URL: &str = "https://192.168.10.108:8081/v1";
pub const FALLBACK_MODEL: &str = "akta-internal";
const DEFAULT_CONTEXT_TOKENS: usize = 8192;
const DEV_BASE_URL_ENV: &str = "AKTA_LLM_BASE_URL";

/// Base URL (including `/v1`) of the internal server. Debug builds may
/// override it with `AKTA_LLM_BASE_URL` for local testing; release builds
/// always use [`DEFAULT_BASE_URL`].
pub fn base_url() -> String {
    if cfg!(debug_assertions) {
        if let Ok(value) = std::env::var(DEV_BASE_URL_ENV) {
            let value = value.trim().trim_end_matches('/');
            if !value.is_empty() {
                return value.to_string();
            }
        }
    }
    DEFAULT_BASE_URL.to_string()
}

fn server_root(base_url: &str) -> &str {
    let trimmed = base_url.trim_end_matches('/');
    trimmed.strip_suffix("/v1").unwrap_or(trimmed)
}

/// HTTP client used exclusively for the internal server. The server sits on
/// a private IP with a self-signed certificate, so certificate and hostname
/// validation are relaxed for this client only; redirects are disabled so it
/// can never be bounced to another host.
pub fn http_client(timeout: Option<Duration>) -> Result<Client, String> {
    let mut builder = Client::builder()
        .danger_accept_invalid_certs(true)
        .danger_accept_invalid_hostnames(true)
        .redirect(Policy::none());
    if let Some(timeout) = timeout {
        builder = builder.timeout(timeout);
    }
    builder
        .build()
        .map_err(|e| format!("Failed to create HTTP client for internal AI: {}", e))
}

fn with_auth(request: reqwest::RequestBuilder, api_key: Option<&str>) -> reqwest::RequestBuilder {
    match api_key.map(str::trim).filter(|k| !k.is_empty()) {
        Some(key) => request.bearer_auth(key),
        None => request,
    }
}

/// Stored tuning options (API key, model, sampling). The endpoint stored in the
/// database is ignored: [`base_url`] always wins.
pub async fn load_config(pool: &SqlitePool) -> CustomOpenAIConfig {
    let stored = SettingsRepository::get_custom_openai_config(pool)
        .await
        .unwrap_or_else(|e| {
            warn!("Failed to read internal AI settings: {}", e);
            None
        });
    let mut config = stored.unwrap_or(CustomOpenAIConfig {
        endpoint: String::new(),
        api_key: None,
        model: String::new(),
        max_tokens: None,
        temperature: None,
        top_p: None,
    });
    config.endpoint = base_url();
    config
}

/// Makes sure the persisted model settings point at the internal server so
/// every part of the app (UI, summary service) sees the same provider.
pub async fn ensure_settings(pool: &SqlitePool) -> Result<(), String> {
    let mut config = load_config(pool).await;
    if config.model.trim().is_empty() {
        config.model = FALLBACK_MODEL.to_string();
    }
    SettingsRepository::save_custom_openai_config(pool, &config)
        .await
        .map_err(|e| e.to_string())?;
    let whisper_model = SettingsRepository::get_model_config(pool)
        .await
        .ok()
        .flatten()
        .map(|c| c.whisper_model)
        .unwrap_or_else(|| "large-v3".to_string());
    SettingsRepository::save_model_config(pool, PROVIDER, &config.model, &whisper_model, None)
        .await
        .map_err(|e| e.to_string())?;
    info!("Internal AI configured at {}", config.endpoint);
    Ok(())
}

/// Model id to send. Uses the configured name when set, otherwise the first
/// model advertised by the server (`GET /v1/models`).
pub async fn resolve_model(client: &Client, config: &CustomOpenAIConfig) -> String {
    let configured = config.model.trim();
    if !configured.is_empty() && configured != FALLBACK_MODEL {
        return configured.to_string();
    }
    let url = format!("{}/models", base_url());
    let response = with_auth(client.get(&url), config.api_key.as_deref())
        .timeout(Duration::from_secs(10))
        .send()
        .await;
    let first_model = match response {
        Ok(resp) if resp.status().is_success() => resp
            .json::<serde_json::Value>()
            .await
            .ok()
            .and_then(|json| first_model_id(&json)),
        Ok(resp) => {
            warn!("Internal AI /models returned {}", resp.status());
            None
        }
        Err(e) => {
            warn!("Internal AI /models request failed: {}", e);
            None
        }
    };
    first_model.unwrap_or_else(|| FALLBACK_MODEL.to_string())
}

fn first_model_id(json: &serde_json::Value) -> Option<String> {
    json.get("data")?
        .as_array()?
        .iter()
        .find_map(|m| m.get("id").and_then(|id| id.as_str()))
        .map(str::to_string)
}

/// Per-request context window reported by llama.cpp (`GET /props`).
pub async fn context_window(client: &Client, api_key: Option<&str>) -> usize {
    let url = format!("{}/props", server_root(&base_url()));
    let response = with_auth(client.get(&url), api_key)
        .timeout(Duration::from_secs(10))
        .send()
        .await;
    let n_ctx = match response {
        Ok(resp) if resp.status().is_success() => resp
            .json::<serde_json::Value>()
            .await
            .ok()
            .and_then(|json| context_from_props(&json)),
        _ => None,
    };
    match n_ctx {
        Some(n) => {
            info!("Internal AI context window: {} tokens", n);
            n
        }
        None => {
            warn!(
                "Could not read context window from internal AI, assuming {}",
                DEFAULT_CONTEXT_TOKENS
            );
            DEFAULT_CONTEXT_TOKENS
        }
    }
}

fn context_from_props(json: &serde_json::Value) -> Option<usize> {
    json.pointer("/default_generation_settings/n_ctx")
        .or_else(|| json.get("n_ctx"))
        .and_then(|v| v.as_u64())
        .filter(|n| *n > 0)
        .map(|n| n as usize)
}

/// Transcript chunk size (in tokens) that leaves room for the prompt template
/// and the generated summary inside the server's context window.
pub fn chunk_token_threshold(context_window: usize) -> usize {
    let reserved = (context_window / 4).max(1024) + 300;
    context_window.saturating_sub(reserved).max(512)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn server_root_strips_v1() {
        assert_eq!(
            server_root("https://10.0.0.1:8081/v1"),
            "https://10.0.0.1:8081"
        );
        assert_eq!(
            server_root("https://10.0.0.1:8081/v1/"),
            "https://10.0.0.1:8081"
        );
        assert_eq!(
            server_root("http://localhost:8080"),
            "http://localhost:8080"
        );
    }

    #[test]
    fn reads_context_from_props() {
        let nested = serde_json::json!({"default_generation_settings": {"n_ctx": 16384}});
        assert_eq!(context_from_props(&nested), Some(16384));
        let flat = serde_json::json!({"n_ctx": 4096});
        assert_eq!(context_from_props(&flat), Some(4096));
        assert_eq!(context_from_props(&serde_json::json!({})), None);
    }

    #[test]
    fn reads_first_model_id() {
        let json = serde_json::json!({"object": "list", "data": [{"id": "qwen3-14b"}]});
        assert_eq!(first_model_id(&json).as_deref(), Some("qwen3-14b"));
        assert_eq!(first_model_id(&serde_json::json!({"data": []})), None);
    }

    #[test]
    fn chunk_threshold_leaves_room_for_output() {
        assert_eq!(chunk_token_threshold(8192), 8192 - 2048 - 300);
        assert_eq!(chunk_token_threshold(4096), 4096 - 1024 - 300);
        assert_eq!(chunk_token_threshold(1024), 512);
    }

    #[test]
    fn release_default_is_internal_server() {
        assert_eq!(DEFAULT_BASE_URL, "https://192.168.10.108:8081/v1");
    }
}

/// End-to-end check against a running llama.cpp (or mock) server.
/// Run with: AKTA_LLM_BASE_URL=https://127.0.0.1:18081/v1 cargo test --lib akta_internal_llm_e2e -- --ignored
#[cfg(test)]
mod e2e {
    use super::*;
    use crate::summary::llm_client::{generate_summary, LLMProvider};

    #[tokio::test]
    #[ignore]
    async fn akta_internal_llm_e2e() {
        let client = http_client(Some(Duration::from_secs(30))).unwrap();
        let config = CustomOpenAIConfig {
            endpoint: base_url(),
            api_key: None,
            model: FALLBACK_MODEL.to_string(),
            max_tokens: None,
            temperature: None,
            top_p: None,
        };
        let model = resolve_model(&client, &config).await;
        assert_ne!(
            model, FALLBACK_MODEL,
            "model should be resolved from /v1/models"
        );
        let ctx = context_window(&client, None).await;
        assert!(ctx > 0);
        let endpoint = base_url();
        let completion = generate_summary(
            &client,
            &LLMProvider::CustomOpenAI,
            &model,
            "",
            "You summarize meetings.",
            "Transcript: we agreed to ship on Friday.",
            None,
            Some(&endpoint),
            Some(256),
            None,
            None,
            None,
            None,
        )
        .await
        .expect("chat completion should succeed");
        println!("model={model} ctx={ctx} completion={completion:?}");
    }
}
